#include <string>
using namespace std;

class Solution {
public:
    string maxValue(string n, int x) {
        int i = 0;
        bool isNeg = (n[0] == '-');
        i = isNeg ? 1 : 0;

        while (i < n.size()) {
            if ((isNeg && n[i] - '0' > x) || (!isNeg && n[i] - '0' < x))
                break;
            ++i;
        }
        return n.substr(0, i) + to_string(x) + n.substr(i);
    }
};
